package com.primehr.performancemanagement;import com.primehr.performancemanagement.api.PerformanceManagementTeamDtos.*;import com.primehr.performancemanagement.application.*;import com.primehr.performancemanagement.application.PmtMemberEligibilityService.EligibleMember;import com.primehr.performancemanagement.domain.PerformanceManagementTeamMember;import com.primehr.shared.exception.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
@SpringBootTest@ActiveProfiles("test")@Transactional class PerformanceManagementTeamIntegrationTest{@Autowired PerformanceManagementTeamService service;@MockBean PmtMemberEligibilityService eligibility;
 @BeforeEach void eligible(){when(eligibility.validate(anyList(),anyString())).thenAnswer(inv->{List<MemberInput> values=inv.getArgument(0);return values.stream().map(v->new EligibleMember(Long.parseLong(v.employeeNo()),v.employeeNo(),"Employee "+v.employeeNo(),10L,20L)).toList();});}
 @Test void effectiveRosterActivatesThenBecomesImmutableAndDeactivates(){TeamResponse draft=service.create("TEST-AGENCY",team(members(),null),"Bearer token",null);assertThat(draft.rosterRevision()).isEqualTo(1);TeamResponse active=service.activate("TEST-AGENCY",draft.id(),new Transition(draft.recordVersion(),"Agency order effective"),"Bearer token",null);assertThat(active.status()).isEqualTo("ACTIVE");assertThat(active.members()).extracting(MemberResponse::employeeNameSnapshot).contains("Employee 1","Employee 2");assertThatThrownBy(()->service.members("TEST-AGENCY",active.id(),new MembersInput(active.recordVersion(),members()),"Bearer token",null)).isInstanceOf(IllegalLifecycleTransitionException.class);TeamResponse inactive=service.deactivate("TEST-AGENCY",active.id(),new Transition(active.recordVersion(),"New PMT designated"),null);assertThat(inactive.status()).isEqualTo("INACTIVE");}
 @Test void duplicatePeriodsMissingChairAndStaleWritesAreRejected(){List<MemberInput> overlap=List.of(member("1",PerformanceManagementTeamMember.Role.CHAIRPERSON,true,LocalDate.of(2026,1,1),LocalDate.of(2026,9,30)),member("1",PerformanceManagementTeamMember.Role.MEMBER,true,LocalDate.of(2026,9,1),null));assertThatThrownBy(()->service.create("TEST-AGENCY",team(overlap,null),"Bearer token",null)).hasMessageContaining("cannot overlap");TeamResponse noChair=service.create("TEST-AGENCY",new SaveTeam("NOCHAIR","No chair","Order",LocalDate.of(2026,1,1),null,List.of(member("2",PerformanceManagementTeamMember.Role.MEMBER,true,LocalDate.of(2026,1,1),null)),null),"Bearer token",null);assertThatThrownBy(()->service.activate("TEST-AGENCY",noChair.id(),new Transition(noChair.recordVersion(),"activate"),"Bearer token",null)).hasMessageContaining("one effective CHAIRPERSON");assertThatThrownBy(()->service.update("TEST-AGENCY",noChair.id(),new SaveTeam("NOCHAIR","No chair","Order",LocalDate.of(2026,1,1),null,members(),99L),"Bearer token",null)).isInstanceOf(OptimisticConflictException.class);}
 @Test void ineligibleEmployeeDependencyFailsClosed(){when(eligibility.validate(anyList(),anyString())).thenThrow(new com.primehr.integration.humanresource.HumanResourceDependencyException("inactive",null));assertThatThrownBy(()->service.create("TEST-AGENCY",team(members(),null),"Bearer token",null)).isInstanceOf(com.primehr.integration.humanresource.HumanResourceDependencyException.class);}
 private static SaveTeam team(List<MemberInput> members,Long version){return new SaveTeam("PMT-2026","Performance Management Team","Agency Order 1",LocalDate.of(2026,1,1),null,members,version);}private static List<MemberInput>members(){return List.of(member("1",PerformanceManagementTeamMember.Role.CHAIRPERSON,true,LocalDate.of(2026,1,1),null),member("2",PerformanceManagementTeamMember.Role.SECRETARIAT,false,LocalDate.of(2026,1,1),null));}private static MemberInput member(String no,PerformanceManagementTeamMember.Role role,boolean voting,LocalDate from,LocalDate to){return new MemberInput(no,role,voting,from,to,"Order",null);}}
